  public void InvoiceManagement() throws Exception {
    ScenarioManager.scenario("Create an Invoice with Generated Data")
        .given(dataSteps.createInvoiceRequest())
        .when(createInvoiceSteps.createInvoice())
        .then(cleanupSteps.cleanup())
        .execute();

    ScenarioManager.scenario("Verify Created Invoice in Oracle EBS")
        .given(dataSteps.createInvoiceRequest())
        .when(createInvoiceSteps.createInvoice())
        .and(waitForInvoiceInDatabaseSteps.waitForInvoiceInDatabase())
        .then(verifyCreatedInvoiceSteps.verifyCreatedInvoice())
        .execute();
  }

  static class DataSteps {

    private Faker faker;

    @Step("Create invoice request")
    public InvoiceRequest createInvoiceRequest() {
      InvoiceRequest invoiceRequest = new InvoiceRequest();
      invoiceRequest.setCustomerId(faker.number().digits(4).intValue());
      invoiceRequest.setInvoiceDate(faker.date().past(30, ChronoUnit.DAYS));
      invoiceRequest.setTotalAmount(faker.number().randomDouble(2, 50, 1000));
      return invoiceRequest;
    }

    @Autowired
    public void setFaker(Faker faker) {
      this.faker = faker;
    }
  }

  static class CreateInvoiceSteps {

    private InvoiceManagementApplication application;

    @Step("Create Invoice")
    public void createInvoice() throws Exception {
      InvoiceRequest invoiceRequest = new DataSteps().createInvoiceRequest();
      InvoiceResponse invoiceResponse = this.application.postInvoice(invoiceRequest);
      assertEquals(HttpStatus.CREATED.value(), invoiceResponse.getStatusCode().value());
    }

    @Autowired
    public void setApplication(InvoiceManagementApplication application) {
      this.application = application;
    }
  }

  static class VerifyCreatedInvoiceSteps {

    private InvoiceManagementRepository invoiceManagementRepository;

    @Step("Verify created invoice")
    public void verifyCreatedInvoice() {
      long customerId = new DataSteps().createInvoiceRequest().getCustomerId();
      Optional<Invoice> invoiceOptional = this.invoiceManagementRepository.findByCustomerId(customerId);
      assert invoiceOptional.isPresent();
      assertEqual(invoiceOptional.get().getTotalAmount(), new DataSteps().createInvoiceRequest().getTotalAmount());
    }

    @Autowired
    public void setInvoiceManagementRepository(InvoiceManagementRepository invoiceManagementRepository) {
      this.invoiceManagementRepository = invoiceManagementRepository;
    }
  }

  static class CleanUpSteps {

    @Step("Cleanup")
    public void cleanup() {
      // Выполните здесь очистку тестов駐
    }
  }

  static class WaitForInvoiceInDatabaseSteps {

    private InvoiceManagementApplication application;

    @Step("Wait for invoice in database")
    public void waitForInvoiceInDatabase() throws Exception {
      long customerId = new DataSteps().createInvoiceRequest().getCustomerId();
      int secondsToWait = 0;
      boolean invoiceFound = false;
      while (!invoiceFound && secondsToWait < 60) {
        try {
          Thread.sleep(1000);
          secondsToWait++;
          Optional<Invoice> invoiceOptional = this.application.invoiceManagementRepository.findByCustomerId(customerId);
          invoiceFound = invoiceOptional.isPresent();
        } catch (InterruptedException e) {
          throw new RuntimeException(e);
        }
      }
      assert invoiceFound;
    }

    @Autowired
    public void setApplication(InvoiceManagementApplication application) {
      this.application = application;
    }
  }
}
```

В приведенном выше примере:

- Классы `DataSteps`, `CreateInvoiceSteps`, `VerifyCreatedInvoiceSteps`, `CleanUpSteps`, и `WaitForInvoiceInDatabaseSteps` реализуют конечные шаги, которые выполняют действия, описанные в Gauge фичах.
- `InvoiceManagementApplication` представляет собой сервис Spring Boot, который содержит необходимую логику для выполнения HTTP-запросов и манипуляции с базой данных Oracle EBS.
- `InvoiceManagementIntegrationTests` - точка входа, используемая Gauge для выполнения интеграционных тестов на primaryStage.

