import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

public class ColorCategory {

    private static final Map<String, String> COLOR_TO_CATEGORY_MAP = Map.of(
            "LI", "Сирень",
            "DA", "Маргаритка",
            "MA", "Бархатцы",
            "CH", "Хризантема"
    );

    public static Map<String, List<String>> groupByCategory(List<String> colorNames) {
