        // Условие для проверки злорадства
        if (userInput.Contains("schadenfreude"))
        {
            Console.WriteLine("Чувство, о котором вы думаете, — это злорадство.");
        }
        else if (userInput.Contains("ennui"))
        {
            Console.WriteLine("Чувство, о котором вы думаете, — это тоска.");
        }
        else if (userInput.Contains("weltschmerz"))
        {
            Console.WriteLine("Чувство, о котором вы думаете, — это мировая скорбь.");
        }
        else
        {
            // Цикл foreach для поиска дополнительных чувств
            var emotions = new List<string>
            {
                "melancholia",
                "schadenfreude",
                "ennui",
                "weltschmerz",
                "nostalgia",
                "bittersweetness"
            };

            foreach (var emotion in emotions)
            {
                if (userInput.Contains(emotion.ToLower()))
                {
                    Console.WriteLine($"Чувство, о котором вы думаете, — это {emotion}.");
                    break; // Условие выполнено, нет смысла продолжать цикл
                }
            }

            // Вывод сообщения о неизвестном чувстве, если его не нашли
            if (!emotions.Contains(userInput.ToLower()))
            {
                Console.WriteLine("Извините, я не знаком с этим чувством. " +
                                  "Можете ли вы предоставить еще более подробную информацию? ");
            }
        }

        Console.ReadKey();
    }
}
```

В программе добавлены дополнительные слова (меланхолия, ностальгия, бittersweetness), которые также могут означать редкие и сложные чувства. Код также был немного изменен с учетом возбуждения любого неизвестного чувства и указания на необходимость получения более подробной информации в этом случае. Хочется отметить, что список дополнительных чувств можно дополнить или изменить в зависимости от ваших потребностей.

