С этой настройкой, методы, содержащие `$set` и `$emit`, которые изменяют внутреннее состояние компонента, будут отмечаться как нарушение правила `no-update-component-state`. Методы, содержащие любые другие вызовы, которые изменяют внутреннее состояние компонента, будут отображать ошибки.

Сообщения проблем пользовательского правила:

- `update-state`: для методов, содержащих `$set` и `$emit`, которые изменяют внутреннее состояние компонента.
- `update-state-method`: для любых других методов, которые изменяют внутреннее состояние компонента. 

Это правило также может быть изменено, чтобы проверять только определенные методы в жизненном цикле компонента, но это будет за пределами текущей задачи. Jerusalem.

Следующее пользовательское правило ESLint для Vue.js проверит, содержит ли обновленный хук жизненного цикла методы, изменяющие внутреннее состояние компонента, и сообщит, вызывают ли эти методы другие методы, меняющие состояние:

```json
{
  "rules": {
    "vue-hooks-dirty-state": "error",
  },
  "plugins": ["vue-eslint-parser"]
}
```

Следующий шаблон проверит, содержит ли метод, указанный в параметрах, модифицирующие выражения (то есть добавляет, убирает или обновляет состояние компонента), и проверяет, вызывается ли он внутри обновленного хука жизненного цикла (то есть `beforeUpdate`, `updated`, `beforeCreate`, `created`, `beforeMount`, `mounted`, `beforeDestroy`, `destroyed` и `activated`, `deactivated`) и те же модифицирующие выражения присутствуют внутри вызываемого метода:

```javascript
/* .eslintrc.js */

module.exports = {
  plugins: ["vue"],
  rules: {
    "vue-hooks-dirty-state": {
      meta: {
        type: "suggestion",
        docs: {
          description: "Avoid modifying component state in life cycle hooks.",
          category: "Best Practices",
        },
        fixable: "code",
      },
      create(context) {
        const modificationExpressions = [
          {name: " pushes ", regex: /^\s*\.push\s*(\()?\s*(.+?)\s*(\))?\s*$/ },
          {name: " unshift ", regex: /^\s*\.unshift\s*(\()?\s*(.+?)\s*(\))?\s*$/ },
          {name: " splice ", regex: /^\s*\.splice\s*\(\s*(\d+)\s*,\s*(\d+)\s*\s*(\()?\s*(.+?)\s*(\))?\s*\)\s*$/ },
          {name: " filter ", regex: /^\s*\.filter\s*(\()?\s*(.+?)\s*(\))?\s*$/ },
          {name: " sort ", regex: /^\s*\.sort\s*(\()?\s*(.+?)\s*(\))?\s*$/ },
          {name: " reverse ", regex: /^\s*\.reverse\s*(\()?\s*(\))?\s*$/ },
          {name: " $set ", regex: /^\s*\.(\$|\_)\s*set\s*\(\s*(.+?)\s*,\s*(.+?)\s*\)\s*$/ },
          {name: " $delete ", regex: /^\s*\.(\$|\_)\s*delete\s*\(\s*(.+?)\s*,\s*(.+?)\s*\)\s*$/ },
        ];

        function isModificationExpression(node, expressions) {
          return expressions.some((expression) => {
            const regex = new RegExp(expression.regex, "i");
            return regex.test(node.argument && node.argument.type === "Literal" ? node.argument.value : node.argument);
          });
        }

        function report(context, message, node) {
          const { line, column } = node.loc.start;
          context.report({
            loc: { line, column },
            message: message.replace("$method", node.callee.name),
          });
        }

        return {
          "Program:exit"() {
            // Collect all functions 
            const lifeCycleHooks = ["beforeUpdate", "updated", "beforeCreate", "created", "beforeMount", "mounted", "beforeDestroy", "destroyed", "activated", "deactivated"];
            const functionsToCheck = [];
            context.getRoot().findNodes("CallExpression", {
              callee: {
                name: "this",
                object: {
                  name: "options",
                  object: {
                    property: {
                      name: "methods",
                      shorthand: true,
                    },
                  },
                },
              },
              arguments: {
                node: (node) => lifeCycleHooks.includes(node.name),
              },
            }).forEach((node) => {
              functionsToCheck.push(node);
            });

            functionsToCheck.forEach((node) => {
              const method = node.callee.property.name;

              node.argument.body.body.forEach((stmt) => {
                if (stmt.type === "ExpressionStatement") {
                  if (isModificationExpression(stmt.expression, modificationExpressions)) {
                    report(context, `"${method}" modifies component state.`, stmt.expression);
                  }

                  // Check recursive calls
                  if (stmt.expression.callee) {
                    const calleeMethod = stmt.expression.callee.property.name;
                    if (isModificationExpression(stmt.expression, modificationExpressions)) {
                      report(context, `"${method}" calls "${calleeMethod}" which modifies component state.`, stmt.expression);
                    }

                    // Recursively check inside invoked function
                    context.walk(stmt.expression, (callExpr) => {
                      if (callExpr.callee && callExpr.callee.property) {
                        const calleeMethod = callExpr.callee.property.name;
                        if (isModificationExpression(callExpr, modificationExpressions)) {
                          report(context, `"${method}" calls "${calleeMethod}" which modifies component state.`, callExpr);
                        }
                      }
                    });
                  }
                }
              });
            });
          },
        };
      },
    },
  },
};
```

Это правило расширяет ESLint на `vue-eslint-parser` плагин, который позволяет определить, вызывается ли метод внутри определенных жизненных цикловых хуков Vue.js. Он также проверяет, изменяет ли метод внутреннее состояние компонента, и проверяет, не вызываются ли такие методы внутри других методов, которые также изменяют внутреннее состояние. 

