  rules: {
    'no-mutating-props': 'off',
    'no-mutating-methods': 'off',
    'vue/no-changing-original-event': 'off',
    'vue/no-mutating-props': 'error',
    'vue/no-mutating-methods-in-watch': 'error',
    'vue/no-mutating-array': 'error',
    'vue/no-mutating-object': 'error',
    'vue/no-mutating-v-model': 'error'
  },
